--- /dev/null
+++ b/test/fixtures/cases/degradations.mjs
@@ -0,0 +1,65 @@
+/**
+ * One merge carrying every conflict this project computes but refuses to
+ * explain in its own words: a submodule pointer, a binary file, a symbolic
+ * link, and a path that is a file on one side and a symlink on the other.
+ *
+ *   git -C .tmp/fixtures/degradations merge-tree --write-tree -z main feature | cat -v
+ *     …^@1^@lib^@CONFLICT (submodule not initialized)^@Failed to merge submodule lib (not checked out)
+ *     ^@1^@lib^@CONFLICT (contents)^@CONFLICT (submodule): Merge conflict in lib
+ *     ^@1^@pic.bin^@CONFLICT (binary)^@warning: Cannot merge binary files: pic.bin (main vs. feature)
+ *     ^@1^@pic.bin^@Auto-merging^@…
+ *     ^@1^@pic.bin^@CONFLICT (contents)^@…
+ *     ^@1^@link^@CONFLICT (contents)^@CONFLICT (content): Merge conflict in link
+ *     ^@2^@swap.txt^@swap.txt~main^@CONFLICT (distinct modes)^@CONFLICT (distinct
+ *      types): swap.txt had different types on each side; renamed one of them so
+ *      each can be recorded somewhere.^@                    (exit 1)
+ *
+ * Each has to reach `unsupported[]` with git's own sentence, because the widget
+ * has no honest wording of its own for any of them (plan §2.8).
+ *
+ * The submodule pointers are object ids that exist nowhere. That is what makes
+ * the fixture one deterministic directory instead of two repositories, and it
+ * is the "not initialized" spelling of the same conflict — a checked-out
+ * submodule emits `CONFLICT (submodule)`, reproduced separately and mapped to
+ * the same kind.
+ */
+/** Git calls a blob binary when it finds a NUL byte in the first 8000 bytes. */
+const NUL = "\u0000";
+
+export default {
+  name: "degradations",
+  branches: { into: "main", from: "feature" },
+
+  base: [
+    {
+      message: "base",
+      write: {
+        "pic.bin": `PNG${NUL}${NUL}base bytes\n`,
+        "swap.txt": "swappable\n",
+      },
+      symlink: { link: "target-base" },
+      gitlink: { lib: "1111111111111111111111111111111111111111" },
+    },
+  ],
+
+  into: [
+    {
+      message: "main changes all four",
+      write: {
+        "pic.bin": `PNG${NUL}${NUL}main bytes\n`,
+        "swap.txt": "swappable\nmain\n",
+      },
+      symlink: { link: "target-main" },
+      gitlink: { lib: "2222222222222222222222222222222222222222" },
+    },
+  ],
+
+  from: [
+    {
+      message: "feature changes all four differently",
+      write: { "pic.bin": `PNG${NUL}${NUL}feature bytes\n` },
+      symlink: { link: "target-feature", "swap.txt": "somewhere-else" },
+      gitlink: { lib: "3333333333333333333333333333333333333333" },
+    },
+  ],
+};
