+/**
+ * `feature` contains every commit of `main` and two more.
+ *
+ *   git -C .tmp/fixtures/fast-forward merge-base --is-ancestor main feature
+ *     (exit 0)
+ *   git -C .tmp/fixtures/fast-forward merge-tree --write-tree -z main feature
+ *     e4e5607…  — which is `feature^{tree}`               (exit 0)
+ *
+ * Nothing of the reader's can be affected, because there is nothing of theirs
+ * that the other branch does not already have. The word "fast-forward" is
+ * banned from the rendered text (plan §3.5); the outcome identifier is not.
+ */
+export default {
+  name: "fast-forward",
+  branches: { into: "main", from: "feature" },
+
+  base: [{ message: "base", write: { "a.txt": "a\n" } }],
+  into: [],
+  from: [
+    { message: "feature edits a", write: { "a.txt": "a\nfeature\n" } },
+    { message: "feature adds new", write: { "new.txt": "new\n" } },
+  ],
+};
