+/**
+ * A clean merge in which one side stops a path being a file.
+ *
+ *   git -C .tmp/fixtures/typechange merge-tree --write-tree main feature
+ *     3c62910…                                          (exit 0)
+ *   git -C .tmp/fixtures/typechange diff -M --name-status main 3c62910…
+ *     T	script
+ *
+ * No conflict, nothing for git to ask about — and `T` is a `--name-status`
+ * letter the first version of the classifier refused outright, which would
+ * have thrown away an entire explainable merge over one row. The reader is
+ * told they get the other side's version, and `effect.onInto.status` carries
+ * the fact that what arrives is not a file.
+ */
+export default {
+  name: "typechange",
+  branches: { into: "main", from: "feature" },
+
+  base: [
+    {
+      message: "base",
+      write: { script: "run me\n", "other.txt": "x\n" },
+    },
+  ],
+
+  into: [{ message: "main edits something else", write: { "other.txt": "x\nmain\n" } }],
+
+  from: [{ message: "feature makes script a link", symlink: { script: "tools/real-script" } }],
+};
