+/**
+ * A conflict short type VisualMerge has no mapping for, produced by a real
+ * repository rather than fabricated bytes.
+ *
+ *   git -C .tmp/fixtures/unknown-type merge-tree --write-tree -z main feature | cat -v
+ *     629985b…^@^@1^@dir^@CONFLICT(directory rename unclear split)^@CONFLICT
+ *     (directory rename split): Unclear where to rename dir to; it was renamed
+ *     to multiple other directories, with no destination getting a majority of
+ *     the files.^@                                          (exit 1)
+ *
+ * Two things this fixture is the only one to exercise. The short type is
+ * spelled **without the space** after `CONFLICT`, so a filter expecting
+ * `CONFLICT (` drops the record and the merge reads as clean while git exits 1.
+ * And the record names a *directory* with no index entries, so it can have no
+ * row in `files[]` — `unsupported[]` is the only place it can be said.
+ */
+export default {
+  name: "unknown-type",
+  branches: { into: "main", from: "feature" },
+
+  base: [
+    {
+      message: "base",
+      write: { "dir/f1.txt": "1\n", "dir/f2.txt": "2\n" },
+    },
+  ],
+
+  into: [
+    {
+      message: "main splits dir across two directories",
+      rename: { "dir/f1.txt": "x/f1.txt", "dir/f2.txt": "y/f2.txt" },
+    },
+  ],
+
+  from: [
+    {
+      message: "feature adds a file into dir",
+      write: { "dir/new.txt": "new\n" },
+    },
+  ],
+};
