@@ -0,0 +1,44 @@
+/**
+ * A conflict short type with no mapping, on a path that *does* get a row.
+ *
+ *   git -C .tmp/fixtures/unmapped-kind merge-tree --write-tree -z main feature | cat -v
+ *     7c9531f…^@100644 3e75765… 3^@newdir/new.txt^@^@2^@newdir/new.txt^@dir/new.txt
+ *     ^@CONFLICT (directory rename suggested)^@CONFLICT (file location):
+ *     dir/new.txt added in feature inside a directory that was renamed in main,
+ *     suggesting it should perhaps be moved to newdir/new.txt.^@   (exit 1)
+ *
+ * The companion to `unknown-type`, which covers the same refusal for a record
+ * that can have no row at all. This one has an index entry, so it keys to
+ * `newdir/new.txt` and the row carries `kind: "other"` — the widget says it
+ * cannot explain why git will stop, rather than inventing a reason from the
+ * long message.
+ *
+ * Also the answer to a question the wider `CONFLICT` prefix raises: git exits
+ * **1** for this record even though it is phrased as a suggestion, so treating
+ * every `CONFLICT`-prefixed type as a conflict cannot turn a clean merge into
+ * a refusal.
+ */
+export default {
+  name: "unmapped-kind",
+  branches: { into: "main", from: "feature" },
+
+  base: [
+    {
+      message: "base",
+      write: { "dir/f1.txt": "1\n", "dir/f2.txt": "2\n", "dir/f3.txt": "3\n" },
+    },
+  ],
+
+  into: [
+    {
+      message: "main renames the whole directory",
+      rename: {
+        "dir/f1.txt": "newdir/f1.txt",
+        "dir/f2.txt": "newdir/f2.txt",
+        "dir/f3.txt": "newdir/f3.txt",
+      },
+    },
+  ],
+
+  from: [{ message: "feature adds a file into the old directory", write: { "dir/new.txt": "new\n" } }],
+};
