+/**
+ * Two branches with nothing in common. `merge-tree` refuses outright:
+ *
+ *   git -C .tmp/fixtures/unrelated-histories merge-base --all main feature
+ *     (no output, exit 1)
+ *   git -C .tmp/fixtures/unrelated-histories merge-tree --write-tree -z main feature
+ *     fatal: refusing to merge unrelated histories        (exit 128)
+ *   git -C … merge-tree --write-tree -z --allow-unrelated-histories main feature
+ *     f4b3548…                                            (exit 0)
+ *
+ * The default run has to refuse with the explanatory sentence, because guessing
+ * what merging two unrelated projects means is the tool inventing a merge
+ * nobody asked for (plan §1.3).
+ */
+export default {
+  name: "unrelated-histories",
+  branches: { into: "main", from: "feature" },
+  unrelated: true,
+
+  base: [{ message: "main only", write: { "a.txt": "a\n" } }],
+  from: [{ message: "feature only", write: { "b.txt": "b\n" } }],
+};
