+/**
+ * Every fixture, through the CLI and then through the string table.
+ *
+ * This is the source-side half of the check WP5 runs over *rendered* text: no
+ * browser, so it cannot catch a term the DOM assembles at runtime, and it does
+ * not try to. What it does catch is the failure this package can introduce —
+ * a real report reaching a sentence that is empty, hedged, or written in git's
+ * vocabulary, on one of the six new merges nobody had run before.
+ */
+import { strict as assert } from "node:assert";
+import { test } from "node:test";
+import { mkdirSync, readFileSync, readdirSync, rmSync } from "node:fs";
+import { join } from "node:path";
+import { Ajv2020 } from "ajv/dist/2020.js";
+import type { MergeReport } from "../../src/schema/types.js";
+import { REPO_ROOT, fixtureRepo, runCli } from "../support/fixture.js";
+import { strings } from "../../src/widget/strings.js";
+
+const OUTPUT_DIR = join(REPO_ROOT, ".tmp/reports");
+mkdirSync(OUTPUT_DIR, { recursive: true });
+
+/** Plan §3.5. `tree` is spelled out so the word boundary spares "between". */
+const BANNED = [
+  "HEAD",
+  "ours",
+  "theirs",
+  "ancestor",
+  "merge base",
+  "index",
+  "stage",
+  "blob",
+  "SHA",
+  "fast-forward",
+  "three-dot",
+  "upstream",
+  "rebase",
+  "squash",
+  "cherry-pick",
+  "detached",
+  "tree",
+];
+
+/** The one fixture the CLI refuses by default; `outcomes.test.ts` owns it. */
+const NEEDS_A_FLAG = new Map([["unrelated-histories", ["--allow-unrelated-histories"]]]);
+
+const schema = JSON.parse(
+  readFileSync(join(REPO_ROOT, "src/schema/merge-report.schema.json"), "utf8"),
+);
+const validate = new Ajv2020({ allErrors: true, strict: true }).compile(schema);
+
+function fixtureNames(): string[] {
+  return readdirSync(join(REPO_ROOT, "test/fixtures/cases"))
+    .filter((name) => name.endsWith(".mjs"))
+    .map((name) => name.replace(/\.mjs$/, ""))
+    .sort();
+}
+
+function reportFor(fixture: string): MergeReport {
+  const path = join(OUTPUT_DIR, `sweep-${fixture}.json`);
+  rmSync(path, { force: true });
+  const extra = NEEDS_A_FLAG.get(fixture) ?? [];
+  const run = runCli(["main", "feature", "--repo", fixtureRepo(fixture), "-o", path, ...extra]);
+  assert.equal(run.status, 0, `${fixture}: the CLI failed: ${run.stderr}`);
+  return JSON.parse(readFileSync(path, "utf8")) as MergeReport;
+}
+
+/** Every sentence the verdict and the ledger would put on the page. */
+function sentencesOf(report: MergeReport): string[] {
+  return [
+    strings.direction(report),
+    strings.verdictHeadline(report),
+    strings.verdictYourWork(report),
+    strings.actionLine(report),
+    strings.bandEmptyStop(report),
+    strings.otherFilesUntouched(report.summary.yourUntouchedChangedFiles) ?? "",
+    ...report.files.map((entry) => strings.rowVerdict(entry, report)),
+    ...report.unsupported.map((item) => item.gitMessage ?? item.detail ?? item.reason),
+  ];
+}
+
+test("every fixture produces a report that validates against the schema", () => {
+  for (const fixture of fixtureNames()) {
+    const report = reportFor(fixture);
+    assert.ok(validate(report), `${fixture}: ${JSON.stringify(validate.errors, null, 2)}`);
+  }
+});
+
+test("no fixture produces a sentence with nothing in it", () => {
+  // An empty string where a verdict belongs is the blank box invariant 9
+  // forbids, arriving one row at a time.
+  for (const fixture of fixtureNames()) {
+    for (const sentence of sentencesOf(reportFor(fixture))) {
+      if (sentence === "") continue;
+      assert.ok(sentence.trim().length > 3, `${fixture}: an empty sentence`);
+    }
+  }
+});
+
+test("no fixture drives a banned git term into a sentence we wrote", () => {
+  // `unsupported[].gitMessage` is exempt and always will be: it is git's own
+  // words, carried verbatim, and paraphrasing it is what plan §1.1 forbids.
+  for (const fixture of fixtureNames()) {
+    const report = reportFor(fixture);
+    const ours = sentencesOf(report).filter(
+      (sentence) => !report.unsupported.some((item) => item.gitMessage === sentence),
+    );
+    for (const sentence of ours) {
+      for (const term of BANNED) {
+        const pattern = new RegExp(`\\b${term.replace(/[-/]/g, "\\$&")}s?\\b`, "i");
+        assert.ok(!pattern.test(sentence), `${fixture}: "${term}" in: ${sentence}`);
+      }
+    }
+  }
+});
+
+test("a merge git will stop on never reads as calm anywhere", () => {
+  for (const fixture of fixtureNames()) {
+    const report = reportFor(fixture);
+    if (!report.summary.willStop) continue;
+    assert.match(strings.verdictHeadline(report), /Git will stop/);
+    // Band 1 is empty when git stops on something that is not a file, and its
+    // empty state then has to agree with the verdict above it.
+    assert.match(strings.bandEmptyStop(report), /Git will stop/);
+  }
+});
