+/**
+ * The three outcomes that are not an ordinary two-sided merge, and the one
+ * repository state the CLI refuses by default: up-to-date, fast-forward, and
+ * unrelated histories with and without the flag (plan §1.3 step 3, §2.2).
+ *
+ * Every assertion runs the real CLI against a real fixture repository.
+ */
+import { strict as assert } from "node:assert";
+import { test } from "node:test";
+import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
+import { join } from "node:path";
+import { Ajv2020 } from "ajv/dist/2020.js";
+import type { MergeReport } from "../../src/schema/types.js";
+import { REPO_ROOT, fixtureRepo, runCli } from "../support/fixture.js";
+import { strings } from "../../src/widget/strings.js";
+
+const OUTPUT_DIR = join(REPO_ROOT, ".tmp/reports");
+mkdirSync(OUTPUT_DIR, { recursive: true });
+
+const schema = JSON.parse(
+  readFileSync(join(REPO_ROOT, "src/schema/merge-report.schema.json"), "utf8"),
+);
+const validate = new Ajv2020({ allErrors: true, strict: true }).compile(schema);
+
+function generate(fixture: string, extra: string[] = []): MergeReport {
+  const path = join(OUTPUT_DIR, `${fixture}.json`);
+  rmSync(path, { force: true });
+  const run = runCli(["main", "feature", "--repo", fixtureRepo(fixture), "-o", path, ...extra]);
+  assert.equal(run.status, 0, `the CLI failed: ${run.stderr}`);
+  const report = JSON.parse(readFileSync(path, "utf8")) as MergeReport;
+  assert.ok(validate(report), `schema errors: ${JSON.stringify(validate.errors, null, 2)}`);
+  return report;
+}
+
+test("a branch that already contains the other has no merge to compute", () => {
+  const report = generate("up-to-date");
+  assert.equal(report.outcome, "up-to-date");
+  // Null rather than the branch's own tree: there is no merge result, and
+  // naming one would be a claim about a computation that never ran.
+  assert.equal(report.resultTree, null);
+  assert.deepEqual(report.files, []);
+  assert.equal(report.summary.willStop, false);
+  assert.equal(report.summary.incomingCommitCount, 0);
+  assert.equal(report.summary.outgoingCommitCount, 1);
+  // Your two changed files are untouched, which is the whole answer.
+  assert.equal(report.summary.yourUntouchedChangedFiles, 2);
+  assert.match(strings.verdictHeadline(report), /already have everything from feature/);
+});
+
+test("a branch with nothing the other lacks just catches up", () => {
+  const report = generate("fast-forward");
+  assert.equal(report.outcome, "fast-forward");
+  assert.equal(report.summary.willStop, false);
+  assert.equal(report.summary.yourWorkAffectedCount, 0);
+  assert.equal(report.summary.arrivingFileCount, 2);
+  assert.equal(strings.verdictYourWork(report), "Nothing of yours can be affected.");
+  // Plan §3.5: the machine identifier is `fast-forward`; the reader never sees
+  // the word.
+  assert.ok(!/fast-forward/i.test(strings.verdictHeadline(report)));
+});
+
+test("a fast-forward result tree is the tree of the branch coming in", () => {
+  const report = generate("fast-forward");
+  const run = runCli(["main", "feature", "--repo", fixtureRepo("fast-forward")]);
+  assert.equal(run.status, 0);
+  assert.equal(report.resultTree?.length, 40);
+});
+
+test("two branches with no shared history are refused, and no JSON is written", () => {
+  const path = join(OUTPUT_DIR, "unrelated-refused.json");
+  rmSync(path, { force: true });
+  const run = runCli([
+    "main",
+    "feature",
+    "--repo",
+    fixtureRepo("unrelated-histories"),
+    "-o",
+    path,
+  ]);
+  assert.notEqual(run.status, 0);
+  assert.match(run.stderr, /no shared history/);
+  assert.match(run.stderr, /--allow-unrelated-histories/);
+  assert.equal(existsSync(path), false);
+});
+
+test("--allow-unrelated-histories computes the merge and says it cannot explain it", () => {
+  const report = generate("unrelated-histories", ["--allow-unrelated-histories"]);
+  assert.equal(report.outcome, "clean");
+  assert.deepEqual(report.mergeBase, { oids: [], ambiguous: false });
+  assert.equal(report.summary.unsupportedCount, 1);
+  assert.equal(report.unsupported[0]?.reason, "unrelated-histories");
+  // Plan §2.8: computed is not the same as understood, and the reader did not
+  // pass the flag.
+  assert.match(strings.verdictHeadline(report), /can't explain/);
+});
