+  name: ".rebuild-probe",
+  branches: { into: "main", from: "feature" },
+  base: [{ message: "base", write: { "a.txt": "a\n" } }],
+  from: [{ message: "feature", write: { "a.txt": "a\nfeature\n" } }],
+};
+
+const builder = (await import(
+  pathToFileURL(join(REPO_ROOT, "test/fixtures/build.mjs")).href
+)) as { buildCase: (fixtureCase: unknown) => string };
+
