+/**
+ * The six parser traps of plan §1.3, each named with the wrong answer it
+ * produces if it is missed.
+ *
+ * Every test here was committed **red** against a naive implementation before
+ * the code that makes it pass (plan §6.2, code guidelines §5). The red commits
+ * are the evidence and they stay in the history; a test that was never seen to
+ * fail has not been tested.
+ */
+import { strict as assert } from "node:assert";
+import { test } from "node:test";
+import { classifyConflictKind, groupConflictRecords } from "../../src/cli/classify.js";
+import { conflictRecords, parseMergeTree, readMergeTree } from "../../src/cli/merge-tree.js";
+import { BINARY, REFERENCE } from "../fixtures/merge-tree-output.js";
+
+test("trap 1: reads past the double NUL between the two sections", () => {
+  // The messages section carries its own leading NUL, so the last stage entry's
+  // terminator is immediately followed by a second one. A parser that splits on
+  // NUL and stops at the first empty field reports **zero conflicts on every
+  // conflicted merge** — a clean verdict for a merge git stops on, which is the
+  // false calm the shape document calls fatal to trust.
+  const parsed = parseMergeTree(REFERENCE);
+  assert.equal(parsed.stages.length, 8);
+  assert.equal(parsed.records.length, 5);
+});
+
+test("trap 2: trims the newline git puts inside each message field", () => {
+  // The newline is inside the NUL-delimited field, not between fields, so it
+  // survives the split and ends up rendered in the degradation panel.
+  const messages = conflictRecords(parseMergeTree(REFERENCE).records).map(
+    (record) => record.message,
+  );
+  assert.equal(messages.length, 3);
+  for (const message of messages) {
+    assert.ok(!message.endsWith("\n"), `a trailing newline survived in: ${JSON.stringify(message)}`);
+    // Trimmed, and otherwise byte-identical to the field git wrote. Spelling
+    // the expected sentence out here would put a long git message in a source
+    // file, which `boundaries.test.ts` bans for good reason.
+    assert.ok(REFERENCE.includes(`\0${message}\n\0`), `not a field of the captured output`);
+  }
+});
+
+test("trap 3: filters Auto-merging by the type field, not by record presence", () => {
+  // `Auto-merging` arrives as a record with exactly the shape of a conflict
+  // record. Counting records instead of reading the type turns every silently
+  // combined file into a conflict — crying wolf on the calmest merge there is.
+  assert.deepEqual(
+    conflictRecords(parseMergeTree(REFERENCE).records).map((record) => record.type),
+    ["CONFLICT (contents)", "CONFLICT (modify/delete)", "CONFLICT (rename/rename)"],
+  );
+});
+
+test("trap 4: keeps every record a path emits, so binary is not overwritten", () => {
+  // A binary conflict emits three records for one path. Keying a map on the
+  // path lets the last one win, and the last one is `CONFLICT (contents)` —
+  // so the report says "you both changed the same lines" about a file that has
+  // no lines, and WP6 would then try to render a diff of it.
+  const parsed = parseMergeTree(BINARY);
+  const grouped = groupConflictRecords(conflictRecords(parsed.records), new Set(["p.bin"]), new Set(["p.bin"]));
+  const types = (grouped.rows.get("p.bin") ?? []).map((record) => record.type);
+  assert.deepEqual(types, ["CONFLICT (binary)", "CONFLICT (contents)"]);
+  assert.equal(classifyConflictKind(types, new Set([1, 2, 3])), "binary");
+});
+
+test("trap 5: tells add/add from a content conflict by stage presence alone", () => {
+  // Both emit the short type `CONFLICT (contents)`; only the long message says
+  // which, and the long message may not be parsed. Stages 2 and 3 without
+  // stage 1 means neither side had the file at the start.
+  assert.equal(classifyConflictKind(["CONFLICT (contents)"], new Set([2, 3])), "add-add");
+  assert.equal(classifyConflictKind(["CONFLICT (contents)"], new Set([1, 2, 3])), "content");
+});
+
+test("trap 6: refuses exit 1 with no tree id instead of reporting a clean merge", () => {
+  // `merge-tree --write-tree -z main nosuchbranch` exits 1 with empty stdout —
+  // the same exit code as a conflicted merge (plan §0.2). A CLI that reads
+  // exit 1 as "conflicts" and empty stdout as "no conflicted files" emits a
+  // clean verdict for a merge it never computed, reachable through a typo.
+  assert.throws(
+    () =>
+      readMergeTree({
+        stdout: "",
+        stderr: "merge-tree: nosuchbranch - not something we can merge\n",
+        status: 1,
+      }),
+    /did not begin with a tree id/,
+  );
+});
